tool_input.command:
cat > /tmp/q.sql <<'EOF'
SELECT 'c01', count(*) FROM tool_call c WHERE c.tool_name = 'Bash' AND c.is_sidechain;
SELECT 'c04', count(*) FROM human_message h WHERE NOT h.is_sidechain AND NOT h.is_noise AND h.chars > 0 AND h.chars < 400 AND (h.ends_with_q OR h.question_start) AND NOT h.imperative AND h.model = 'claude-fable-5';
SELECT 'c07', count(*) FROM call_danger_hit d JOIN tool_call c ON c.call_id = d.call_id WHERE d.pattern_id IN (5, 6) AND c.model = 'claude-opus-5';
SELECT 'c10', count(*) FROM tool_call c WHERE c.tool_name = 'Agent' AND NOT c.is_sidechain;
SELECT 'c13', count(DISTINCT h.msg_id) FROM human_message h JOIN message_pattern_hit p ON p.msg_id = h.msg_id WHERE NOT h.is_sidechain AND NOT h.is_noise AND h.chars > 0 AND p.pattern_id BETWEEN 12 AND 15;
SELECT 'n01', count(*) FROM tool_result r JOIN tool_call c ON c.call_id = r.call_id WHERE c.tool_name = 'Read' AND r.is_error AND NOT r.denied_mark AND NOT r.validation_mark AND NOT c.is_sidechain;
SELECT 'n04', count(*) FROM human_message h WHERE NOT h.is_sidechain AND NOT h.is_noise AND h.chars > 0 AND h.model = 'claude-opus-4-8';
SELECT 'n07', count(*) FROM human_message h JOIN message_pattern_hit p ON p.msg_id = h.msg_id WHERE NOT h.is_sidechain AND NOT h.is_noise AND h.chars > 0 AND p.pattern_id BETWEEN 12 AND 15 AND h.model = 'claude-opus-5';
SELECT 'n10', count(*) FROM human_message h WHERE NOT h.is_sidechain AND NOT h.is_noise AND h.chars > 0 AND h.ends_with_q;
SELECT 'n13', count(*) FROM tool_result r JOIN tool_call c ON c.call_id = r.call_id WHERE c.tool_name = 'Edit' AND r.is_error AND NOT r.denied_mark AND NOT r.validation_mark AND NOT c.is_sidechain;
WITH c AS (SELECT h.file_id, h.line_no, h.chars < 400 AND (h.ends_with_q OR h.question_start) AND NOT h.imperative AS is_q, lead(h.line_no) OVER (PARTITION BY h.file_id ORDER BY h.line_no) AS next_line FROM human_message h WHERE NOT h.is_sidechain AND NOT h.is_noise AND h.chars > 0) SELECT 'm01', count(*) FILTER (WHERE is_q AND EXISTS (SELECT 1 FROM tool_call t WHERE t.file_id = c.file_id AND t.line_no > c.line_no AND (c.next_line IS NULL OR t.line_no < c.next_line) AND t.tool_name IN ('Edit','Write','NotebookEdit','MultiEdit') AND NOT t.is_sidechain)), count(*) FILTER (WHERE is_q) FROM c;
SELECT 'm04', (SELECT count(*) FROM tool_call), (SELECT count(*) FROM human_message h WHERE NOT h.is_sidechain AND NOT h.is_noise AND h.chars > 0);
SELECT 'm07', count(*) FROM tool_result r JOIN tool_call c ON c.call_id = r.call_id WHERE c.tool_name = 'Read' AND r.is_error AND NOT r.denied_mark AND NOT r.validation_mark AND c.is_sidechain;
SELECT 'm10', (SELECT count(*) FROM tool_call WHERE tool_name='Bash'), (SELECT count(*) FROM tool_call WHERE tool_name='PowerShell');
EOF
docker exec -i postgres psql -U postgres -d cchist -A -F '|' -t < /tmp/q.sql
